//! OPT-737 native physical allocation/copy witness across increasing full
//! response row counts. The same app, inputs and independent wire oracle run
//! against the current generated Bytes writer and the reconstructed pre-writer
//! concat codec. Counters cover generated C allocator requests and explicit
//! memcpy calls only; no RSS, wall time, interpreter/Wasm or agent-cost claim.
use super::*;
use semaprax::ast::{FieldDeclaration, Program, Type, TypeDeclaration, TypeDeclarationKind};
use serde_json::Value;

/// Last commit whose CollectionResponse generator concatenated Strings.
const LEGACY_COMMIT: &str = "a8a39a0a08ecfe896a1a510d57c35ff7f9475467";
/// Byte-exact suffix of `src/project/json_codec/utf8/text.spx` at
/// [`LEGACY_COMMIT`], from its owned-valid marker, as `response_source` read it.
const LEGACY_TEXT: &str = include_str!("legacy_response_text.spx");
/// Increasing full response cardinalities through the profile's 256 maximum.
const ROWS: [usize; 5] = [0, 1, 8, 64, 256];
const PHASES: [&str; 4] = ["preflight", "one-short-refusal", "exact", "reentry"];

// --- Reconstruction of the LEGACY_COMMIT generator, kept to its exact text.
fn legacy_fields(record: &TypeDeclaration) -> &[FieldDeclaration] {
    match &record.kind {
        TypeDeclarationKind::Record { fields } => fields,
        _ => unreachable!("validated record"),
    }
}

fn legacy_literal(value: &str) -> String {
    format!("\"{}\"", value.replace('\\', "\\\\").replace('"', "\\\""))
}

fn legacy_value(record: &TypeDeclaration, field: &FieldDeclaration, indexed: bool) -> String {
    if indexed {
        format!(
            "vec_field<{}>(values,at,{})",
            record.name,
            legacy_literal(&field.name)
        )
    } else if field.ty == Type::String {
        format!("string_as_str(value.{})", field.name)
    } else {
        format!("value.{}", field.name)
    }
}

fn legacy_length(record: &TypeDeclaration, field: &FieldDeclaration, indexed: bool) -> String {
    let value = legacy_value(record, field, indexed);
    match field.ty {
        Type::String => format!("json_{}_response_utf8_quoted_len({value})", record.name),
        Type::Bool => format!("if {value}{{4usize}}else{{5usize}}"),
        Type::Usize => format!("jv_usize_len({value})"),
        Type::U8 => format!("usize_from_i64(jv_i64_len(i64_from_u8({value})))"),
        Type::I64 => format!("usize_from_i64(jv_i64_len({value}))"),
        _ => unreachable!("validated scalar/string"),
    }
}

fn legacy_rendered(record: &TypeDeclaration, field: &FieldDeclaration, indexed: bool) -> String {
    let value = legacy_value(record, field, indexed);
    match field.ty {
        Type::String => format!("json_{}_response_utf8_quote({value})", record.name),
        Type::Bool => format!("if {value}{{\"true\"}}else{{\"false\"}}"),
        Type::Usize => format!("string_from_usize({value})"),
        Type::U8 => format!("string_from_i64(i64_from_u8({value}))"),
        Type::I64 => format!("string_from_i64({value})"),
        _ => unreachable!("validated scalar/string"),
    }
}

fn legacy_object(record: &TypeDeclaration, indexed: bool) -> String {
    use std::fmt::Write as _;
    let fs = legacy_fields(record);
    let name = &record.name;
    let id = &record.stable_id;
    let ownership = if fs.iter().any(|field| field.ty == Type::String) {
        "borrow "
    } else {
        ""
    };
    let (suffix, identity_suffix, parameters) = if indexed {
        ("_at", "-at", format!("values:borrow Vec<{name}>,at:usize"))
    } else {
        ("", "", format!("value:{ownership}{name}"))
    };
    let punctuation = 2 + fs.iter().map(|f| f.name.len() + 3).sum::<usize>() + fs.len() - 1;
    let string_fields: Vec<_> = fs.iter().filter(|field| field.ty == Type::String).collect();
    // The witness schema has exactly one String field; the legacy multi-String
    // binding arm is not reconstructed rather than guessed.
    let validity = match string_fields.as_slice() {
        [] => "true".to_owned(),
        [field] => format!(
            "json_{name}_response_owned_valid({})",
            legacy_value(record, field, indexed)
        ),
        _ => unreachable!("one-String witness row"),
    };
    let mut out = format!(
        "@id(\"{id}.json.collection-response.object-len{identity_suffix}\")
fn json_{name}_response_object_len{suffix}({parameters})->usize {{
if !({validity}){{18446744073709551615usize}}else{{{punctuation}usize"
    );
    for field in fs {
        write!(out, "+({})", legacy_length(record, field, indexed)).unwrap();
    }
    writeln!(
        out,
        "}}}}
@id(\"{id}.json.collection-response.object-render{identity_suffix}\")
fn json_{name}_response_object_render{suffix}({parameters})->string {{
if !({validity}){{\"\"}}else{{let output_0=\"{{\";"
    )
    .unwrap();
    for (index, field) in fs.iter().enumerate() {
        let label = legacy_literal(&format!(
            "{}\"{}\":",
            if index == 0 { "" } else { "," },
            field.name
        ));
        writeln!(out, "let label_{index}=string_concat(output_{index},{label});let rendered_{index}={};let output_{}=string_concat(label_{index},rendered_{index});", legacy_rendered(record, field, indexed), index+1).unwrap();
    }
    writeln!(out, "string_concat(output_{},\"}}\")}}}}", fs.len()).unwrap();
    out
}

fn legacy_root(
    root: &TypeDeclaration,
    row: &str,
    metrics: &str,
    items: &str,
    stats: &str,
) -> String {
    use std::fmt::Write as _;
    let name = &root.name;
    let id = &root.stable_id;
    let punctuation = 2
        + legacy_fields(root)
            .iter()
            .map(|field| field.name.len() + 3)
            .sum::<usize>()
        + 1
        + 2;
    let mut out = format!("@id(\"{id}.json.collection-response.encode-result\")
variant {name}JsonCollectionResponseEncode {{
@id(\"{id}.json.collection-response.encoded\") Encoded{{@id(\"{id}.json.collection-response.text\") text:string,}},
@id(\"{id}.json.collection-response.refused\") Refused{{@id(\"{id}.json.collection-response.required\") required:usize,}},
}}
@id(\"{id}.json.collection-response.encoded-len\")
fn json_{name}_collection_response_encoded_len(value:borrow {name})->usize {{
let count=vec_len<{row}>(value.{items});
let mut valid=count<=256usize;
let mut total={punctuation}usize+json_{metrics}_response_object_len(value.{stats});
let mut at=0usize;
while valid && at<count {{
let size=json_{row}_response_object_len_at(value.{items},at);
let comma=if at>0usize{{1usize}}else{{0usize}};
let _ = if size==18446744073709551615usize || total>131072usize-comma || size>131072usize-total-comma {{valid=false;false}}else{{total=total+size+comma;true}};
at=at+1usize;valid && at<count
}}
if valid && total<=131072usize{{total}}else{{18446744073709551615usize}}
}}
@id(\"{id}.json.collection-response.encode\")
fn json_{name}_collection_response_encode(value:borrow {name},output_limit:usize)->{name}JsonCollectionResponseEncode {{
let required=json_{name}_collection_response_encoded_len(value);
if required==18446744073709551615usize || required>output_limit {{{name}JsonCollectionResponseEncode::Refused{{required:required}}}}else{{
let mut text=\"{{\";");
    for (index, field) in legacy_fields(root).iter().enumerate() {
        let key = legacy_literal(&format!(
            "{}\"{}\":",
            if index == 0 { "" } else { "," },
            field.name
        ));
        writeln!(out, "text=string_concat(text,{key});").unwrap();
        if field.name == items {
            writeln!(
                out,
                "text=string_concat(text,\"[\");let mut at=0usize;
while at<vec_len<{row}>(value.{items}) {{
let _ = if at>0usize{{text=string_concat(text,\",\");true}}else{{true}};
text=string_concat(text,json_{row}_response_object_render_at(value.{items},at));
at=at+1usize;at<vec_len<{row}>(value.{items})
}}
text=string_concat(text,\"]\");"
            )
            .unwrap();
        } else {
            writeln!(
                out,
                "text=string_concat(text,json_{metrics}_response_object_render(value.{stats}));"
            )
            .unwrap();
        }
    }
    writeln!(
        out,
        "{name}JsonCollectionResponseEncode::Encoded{{text:string_concat(text,\"}}\")}}
}}
}}"
    )
    .unwrap();
    out
}

/// The legacy fragment merged exactly as that commit's derive merged it.
fn legacy_schema() -> String {
    assert!(LEGACY_TEXT.starts_with("@id(\"__ROW_ID__.json.utf8.owned-valid\")"));
    assert_eq!(LEGACY_TEXT.len(), 1981, "byte-exact legacy template");
    let mut program: Program = parse(SCHEMA, "src/schema.spx").unwrap();
    let declaration = |id: &str| {
        program
            .types
            .iter()
            .find(|ty| ty.stable_id == id)
            .unwrap()
            .clone()
    };
    let (root, row, metrics) = (
        declaration("response.report"),
        declaration("response.item"),
        declaration("response.metrics"),
    );
    let mut fragment = format!("module {};\n", program.module);
    for (module, name, alias) in [
        ("digits", "i64_len", "jv_i64_len"),
        ("write", "usize_len", "jv_usize_len"),
        ("utf8", "scalar_at", "ju_raw_scalar"),
        ("utf8", "sequence_end", "ju_raw_end"),
        ("utf8", "utf8_end", "ju_raw_utf8_end"),
    ] {
        fragment.push_str(&format!("use function @id(\"std.data.json.{module}.{name}\") from std.data.json.{module} as {alias};\n"));
    }
    // Marker rewrites precede substitution; replacement values hold no marker.
    fragment.push_str(
        &LEGACY_TEXT
            .replace("json___ROW___", "json___ROW___response_")
            .replace(".json.utf8.", ".json.collection-response.")
            .replace("__ROW_ID__", &row.stable_id)
            .replace("__ROW__", &row.name)
            .replace("__BOUND__", "64"),
    );
    fragment.push_str(&legacy_object(&row, false));
    fragment.push_str(&legacy_object(&row, true));
    fragment.push_str(&legacy_object(&metrics, false));
    fragment.push_str(&legacy_root(
        &root,
        &row.name,
        &metrics.name,
        "entries",
        "stats",
    ));
    assert!(!fragment.contains("bytes_zeroed") && !fragment.contains("__"));
    let mut generated = parse(&fragment, "src/schema.spx").unwrap();
    for import in generated.module_uses.drain(..) {
        if !program.module_uses.iter().any(|existing| {
            existing.kind == import.kind
                && existing.persistent_id == import.persistent_id
                && existing.target_module == import.target_module
                && existing.alias == import.alias
        }) {
            program.module_uses.push(import);
        }
    }
    program.types.append(&mut generated.types);
    program.functions.append(&mut generated.functions);
    let canonical = format::canonical(&program);
    assert_eq!(
        format::canonical(&parse(&canonical, "src/schema.spx").unwrap()),
        canonical
    );
    canonical
}

// --- Shared app, independent oracle and native probe.
fn app() -> String {
    imports().to_owned()
        + r#"
@id("consumer.prepare") fn prepare(count:usize)->Report requires count<=256usize {
let mut text="";let mut scalar=0usize;
while scalar<64usize{text=string_concat(text,string_from_char(char_from_i64(0)));scalar=scalar+1usize;scalar<64usize}
let seed=Item{number:0,label:text,byte:0u8,count:0usize,active:true};
let seeds=vec_push<Item>(vec_with_capacity<Item>(1usize),seed);
let mut rows=vec_with_capacity<Item>(256usize);let mut at=0usize;
while at<count{let row=vec_clone_at<Item>(seeds,0usize);rows=vec_push<Item>(rows,row);at=at+1usize;at<count}
Report{stats:Metrics{selected:count,total:0,live:true},entries:rows}
}
@id("consumer.required") fn required(value:borrow Report)->usize{encoded_len(value)}
@id("consumer.run") fn run(value:borrow Report,limit:usize,length:usize)->i64{
let outcome=encode(value,limit);match own outcome {
Encoded::Refused{required:n}=>if n==length{1}else{0},
Encoded::Encoded{text}=>0,}}
@id("consumer.render") fn render(value:borrow Report,limit:usize)->Encoded{encode(value,limit)}
@id("consumer.compare") fn compare_chunk(outcome:borrow Encoded,offset:usize,total:usize,expected:borrow Slice<u8>)->bool{
match borrow outcome {
Encoded::Refused{required:n}=>false,
Encoded::Encoded{text}=>{
let actual=string_as_str(text);let width=byte_len(expected);let mut at=0usize;
let mut same=usize_from_i64(str_len_bytes(actual))==total && offset<=total && width<=total-offset;
while same && at<width{same=match str_byte_at(actual,offset+at){Option::Some{value:a}=>match byte_get(expected,at){Option::Some{value:b}=>a==b,Option::None{}=>false,},Option::None{}=>false,};at=at+1usize;same && at<width}
same
},}}
@id("consumer.release") fn release(outcome:own Encoded)->i64{0}
@id("consumer.consume") fn consume(value:own Report)->i64{0}
@id("consumer.main") fn main()->i64{
let value=prepare(0usize);let n=required(value);let refused=run(value,n-1usize,n);let outcome=render(value,n);let open=[123u8];let same=compare_chunk(outcome,0usize,n,array_as_slice(open));let released=release(outcome);let dropped=consume(value);let checked=if same{0}else{1};refused+checked+released+dropped
}
"#
}

/// The `collection_response_full_256_rows_at_64_bytes` oracle, per row count.
fn oracle(rows: usize) -> (String, String, usize) {
    let row = format!(
        "{{\"number\":0,\"label\":\"{}\",\"byte\":0,\"count\":0,\"active\":true}}",
        "\\u0000".repeat(64)
    );
    let head =
        format!("{{\"stats\":{{\"selected\":{rows},\"total\":0,\"live\":true}},\"entries\":[");
    let length = head.len() + rows * row.len() + rows.saturating_sub(1) + 2;
    let whole = format!("{head}{}]}}", vec![row.as_str(); rows].join(","));
    assert_eq!(whole.len(), length);
    let parsed: Value = serde_json::from_str(&whole).unwrap();
    let entries = parsed["entries"].as_array().unwrap();
    assert_eq!(entries.len(), rows);
    let label = "\0".repeat(64);
    assert!(entries
        .iter()
        .all(|entry| entry["label"].as_str() == Some(label.as_str())));
    (head, row, length)
}

fn hex(id: &str) -> String {
    id.bytes().map(|byte| format!("{byte:02x}")).collect()
}

fn c_bytes(value: &str) -> String {
    value
        .bytes()
        .map(|byte| byte.to_string())
        .collect::<Vec<_>>()
        .join(",")
}

fn probe(label: &str, root: &std::path::Path) -> Vec<Vec<Value>> {
    let generated = project::with_authenticated_project(&root.join("semaprax.toml"), |snapshot| {
        semaprax::hir::validate(snapshot.entry_program()).map_err(|e| vec![e])?;
        codegen::emit_hir_c(snapshot.entry_program()).map_err(|e| vec![e])
    })
    .unwrap();
    let mut cases = String::new();
    for rows in ROWS {
        let (head, row, length) = oracle(rows);
        cases.push_str(&format!("{{static const uint8_t head[]={{ {} }};static const uint8_t row[]={{ {} }};case_run(&context,{rows},head,{},row,{},{length});}}\n", c_bytes(&head), c_bytes(&row), head.len(), row.len()));
    }
    let observer = include_str!("../../../../native_owned_utf8_settlement_v1/allocations.c");
    let copies = include_str!("../../../../native/string_settlement/bulk_utf8/copies.c");
    let hooks = include_str!("physical_hooks.c");
    let probe = include_str!("physical_probe.c");
    // The emitted Borrow Report ABI separately passes its exact Vec field, and
    // Borrow Encoded the exact owned String leaf of its Encoded case. Both
    // codecs use the same live prepared field, without copying its carrier.
    // Only the expected chunk is an external Slice root; the encoded owner is
    // never relabelled as one.
    let source = format!(
        "#define FIXTURE_TRACK_CALLOC\n{observer}\n{copies}\n{hooks}\n#define main fixture_generated_main\n{generated}\n#undef main\n#undef malloc\n#undef calloc\n#undef realloc\n#undef free\n#undef memcpy\n#define IMPLEMENTATION \"{label}\"\n#define PREPARE spx_decl_{}\n#define REQUIRED(context,input,result) spx_decl_{}((context),(input),&((input)->spx_field_{}),(result))\n#define RUN(context,input,limit,length,result) spx_decl_{}((context),(input),&((input)->spx_field_{}),(limit),(length),(result))\n#define RENDER(context,input,limit,result) spx_decl_{}((context),(input),&((input)->spx_field_{}),(limit),(result))\n#define COMPARE(context,held,offset,total,chunk,result) spx_decl_{}((context),(held),&((held)->spx_payload.spx_case_{}.spx_field_{}),(offset),(total),(chunk),(result))\n#define RELEASE spx_decl_{}\n#define CONSUME spx_decl_{}\n#define REPORT spx_record_{}\n#define ENCODED spx_variant_{}\n{probe}\nint main(void){{struct spx_status_entry entries[16];struct spx_context context={{0}};REQUIRE(spx_context_init(&context,737,entries,16,NULL,NULL,NULL));{cases}(void)puts(\"724\");return 0;}}",
        hex("consumer.prepare"),
        hex("consumer.required"),
        hex("response.report.items"),
        hex("consumer.run"),
        hex("response.report.items"),
        hex("consumer.render"),
        hex("response.report.items"),
        hex("consumer.compare"),
        hex("response.report.json.collection-response.encoded"),
        hex("response.report.json.collection-response.text"),
        hex("consumer.release"),
        hex("consumer.consume"),
        hex("response.report"),
        hex("response.report.json.collection-response.encode-result")
    );
    let mut runs = Vec::new();
    for optimization in ["-O0", "-O2"] {
        let path = root.join(format!("physical{optimization}.c"));
        let binary = root.join(format!("physical{optimization}"));
        std::fs::write(&path, &source).unwrap();
        let build = Command::new("clang")
            .args(["-std=c11", "-Wall", "-Wextra", "-Werror", optimization])
            .arg(&path)
            .arg("-o")
            .arg(&binary)
            .output()
            .unwrap();
        assert!(
            build.status.success(),
            "{}",
            String::from_utf8_lossy(&build.stderr)
        );
        let run = Command::new(&binary).output().unwrap();
        assert!(
            run.status.success() && run.stderr.is_empty(),
            "{label}{optimization}: {}",
            String::from_utf8_lossy(&run.stderr)
        );
        let stdout = String::from_utf8(run.stdout).unwrap();
        let mut lines = stdout.lines().collect::<Vec<_>>();
        assert_eq!(lines.pop(), Some("724"));
        runs.push(
            lines
                .into_iter()
                .map(|line| serde_json::from_str(line).unwrap())
                .collect(),
        );
    }
    // Allocator requests and explicit copies are semantic calls, not
    // optimizer-dependent: both levels must report identical physical rows.
    assert_eq!(runs[0], runs[1], "{label}: O0/O2 physical rows differ");
    runs
}

fn n(row: &Value, key: &str) -> u64 {
    row[key]
        .as_u64()
        .unwrap_or_else(|| panic!("{key} in {row}"))
}

/// Exact (case, phase) order and invariants common to both implementations.
fn phases<'a>(label: &str, rows: &'a [Value]) -> Vec<[&'a Value; 4]> {
    assert_eq!(rows.len(), ROWS.len() * PHASES.len());
    ROWS.iter()
        .enumerate()
        .map(|(case, &count)| {
            let group: [&Value; 4] = std::array::from_fn(|phase| &rows[case * 4 + phase]);
            for (phase, row) in group.iter().enumerate() {
                assert_eq!(row["implementation"].as_str(), Some(label));
                assert_eq!(n(row, "rows"), count as u64);
                assert_eq!(row["phase"].as_str(), Some(PHASES[phase]));
                // Every tracked event is either a Bytes reservation or a String.
                assert_eq!(
                    n(row, "allocation_events"),
                    n(row, "bytes_reservations") + n(row, "string_allocations")
                );
                assert_eq!(n(row, "allocation_events"), n(row, "frees"), "{row}");
                assert!(n(row, "explicit_memcpy_calls") >= n(row, "final_buffer_copy_calls"));
                assert!(n(row, "explicit_memcpy_bytes") >= n(row, "final_buffer_copy_bytes"));
            }
            // Preflight and one-short refusal request nothing physical.
            for row in &group[..2] {
                for key in [
                    "allocation_events",
                    "peak_live_above_input",
                    "final_buffer_copy_bytes",
                ] {
                    assert_eq!(n(row, key), 0, "{row}");
                }
            }
            // Reentry on the same input/context repeats the exact phase.
            let mut exact = group[2].clone();
            let mut again = group[3].clone();
            exact["phase"] = Value::Null;
            again["phase"] = Value::Null;
            assert_eq!(exact, again, "{label}: reentry drift");
            group
        })
        .collect()
}

#[test]
fn generated_writer_reserves_once_and_copies_once_across_full_row_counts_unlike_legacy_concat() {
    let (_, _, maximum) = oracle(256);
    assert!(maximum > 100_000 && maximum <= 131_072);
    let writer_root = install("response-physical-writer", &app(), 64);
    let current = std::fs::read_to_string(writer_root.join("src/schema.spx")).unwrap();
    assert_eq!(
        current
            .matches("bytes_zeroed_bounded(required, 131072usize)")
            .count(),
        1
    );
    let legacy_root = fixture("response-physical-legacy", &legacy_schema());
    std::fs::write(legacy_root.join("src/app.spx"), canonical(&app())).unwrap();
    let legacy_source = std::fs::read_to_string(legacy_root.join("src/schema.spx")).unwrap();
    assert!(
        legacy_source.contains("text = string_concat(text, json_Item_response_object_render_at(")
    );
    assert_ne!(legacy_source, current);

    let writer = probe("writer", &writer_root).remove(0);
    let legacy = probe("legacy", &legacy_root).remove(0);
    let writer = phases("writer", &writer);
    let legacy = phases("legacy", &legacy);
    let mut previous: Option<(u64, u64, u64)> = None;
    for (case, &rows) in ROWS.iter().enumerate() {
        let length = oracle(rows).2 as u64;
        let (now, old) = (writer[case][2], legacy[case][2]);
        // Current writer: one exact Bytes reservation, one final String
        // (u64 length header + payload + NUL), one final buffer copy, and the
        // same event count, frees and live peak at every row count.
        for (key, value) in [
            ("allocation_events", 2),
            ("frees", 2),
            ("bytes_reservations", 1),
            ("reserved_payload_bytes", length),
            ("string_allocations", 1),
            ("string_request_bytes", length + 8 + 1),
            ("final_size_string_allocations", 1),
            ("peak_live_above_input", 2),
            ("final_buffer_copy_calls", 1),
            ("final_buffer_copy_bytes", length),
        ] {
            assert_eq!(n(now, key), value, "writer rows={rows} {key}: {now}");
        }
        // Legacy: never reserves Bytes; its measured String/copy traffic is
        // retained as observed, compared only with the same-row writer.
        for (key, value) in [("bytes_reservations", 0), ("final_buffer_copy_bytes", 0)] {
            assert_eq!(n(old, key), value, "legacy rows={rows} {key}: {old}");
        }
        assert!(n(old, "final_size_string_allocations") >= 1, "{old}");
        assert!(n(old, "explicit_memcpy_bytes") >= length, "{old}");
        assert!(
            n(old, "allocation_events") > n(now, "allocation_events"),
            "{old}"
        );
        assert!(
            n(old, "explicit_memcpy_bytes") > n(now, "explicit_memcpy_bytes"),
            "{old}"
        );
        assert!(
            n(old, "string_request_bytes")
                > n(now, "reserved_payload_bytes") + n(now, "string_request_bytes"),
            "{old}"
        );
        let observed = (
            n(old, "allocation_events"),
            n(old, "string_request_bytes"),
            n(old, "explicit_memcpy_bytes"),
        );
        if let Some(before) = previous {
            assert!(observed.0 > before.0 && observed.1 > before.1 && observed.2 > before.2);
        }
        previous = Some(observed);
        println!(
            "OPT-737 native rows={rows} output={length}: writer events=2 requested={} memcpy={}B; legacy {LEGACY_COMMIT:.9} events={} requested={} memcpy={}B peak_live={}",
            length * 2 + 9,
            n(now, "explicit_memcpy_bytes"),
            observed.0,
            observed.1,
            observed.2,
            n(old, "peak_live_above_input"),
        );
    }
    std::fs::remove_dir_all(writer_root).unwrap();
    std::fs::remove_dir_all(legacy_root).unwrap();
}
